@RequiredArgsConstructor
public class $!{tableName} extends ServiceImpl<$!mapperName, $!doName> implements $!serviceName {
    /**
     * 分页查询 $!{tableInfo.comment} 列表
     * @param req 查询实体
     * @return 分页数据
     */
    public Page<$!pageVoName> pageVo($!queryName req) {
        // 分页参数处理
        Integer currPage = req.getPage();
        Integer pageSize = req.getPageSize();
        currPage = currPage <= 0 ? 1 : currPage;
        pageSize = pageSize <= 0 ? 20 : pageSize;

        // 开启 PageHelper 分页
        PageHelper.startPage(currPage, pageSize);

        // 调用 Mapper 接口方法
        Page<$!pageVoName> pageObj = baseMapper.pageVo(req);
        return pageObj;
    }

    /**
