        $!doName saveDo = new $!doName();
        // 属性拷贝
        BeanUtils.copyProperties(dto, saveDo);
        saveDo.setUpdateTime(new Date()); // 设置更新时间

        return baseMapper.updateById(saveDo) > 0;
    }

    /**
     * 新增 $!{tableInfo.comment} 数据
     * @param dto 实体对象
     * @return 新增结果
     */
