/**
 * $!tableInfo.comment 控制层单元测试
 * * 注意：本测试类使用 Mockito 模拟 Service 层依赖，并使用 MockMvc 模拟 HTTP 请求。
 *
 * @author $!author
 * @since $!date
 */
@ExtendWith(MockitoExtension.class)
public class $!{controllerName}Test {

    // 控制器基础路径: /$!tablePrefix/$!{tool.toCamelCase($!tableInfo.name)}
    private static final String BASE_URL = "/$!tablePrefix/$!tool.toCamelCase($!tableInfo.name)";

    @InjectMocks
    private $!controllerName $!controllerObjName;

    @Mock
    private $!serviceName $!serviceObjName;

    // 用于模拟 HTTP 请求
    private MockMvc mockMvc;

    // 用于将对象序列化为 JSON
    private ObjectMapper objectMapper;

    @BeforeEach
    void setUp() {
        mockMvc = standaloneSetup(this.$!controllerObjName).build();
        objectMapper = new ObjectMapper();
    }

    // --- 辅助方法/常量 ---

    private static final String CODE_PATH = "$.code";
    private static final String ROWS_PATH = "$.rows";


    // --- 接口测试 ---

    /**
     * 测试分页查询接口 /page
     */
    @Test
    void testPage() throws Exception {
        // 1. 模拟 Service 返回数据
        $!pageVoName mockVo = new $!pageVoName();
        // mockVo.setGameRoleName("TestRoleName"); 

        List<$!pageVoName> mockList = Collections.singletonList(mockVo);

        Page<$!pageVoName> page = new Page<>(1, 10);
        page.setTotal(1);
        page.addAll(mockList);

        // Service 方法: pageVo(req)
        // 使用 $!{queryName}.class 提高解析稳定性
        when($!{serviceObjName}.pageVo(any($!{queryName}.class))).thenReturn(page);

        // 2. 构造请求体
        $!queryName query = new $!queryName();
        String jsonQuery = objectMapper.writeValueAsString(query);

        // 3. 执行请求并验证
        mockMvc.perform(post(BASE_URL + "/page")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(jsonQuery))
                .andDo(print())
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.total").value(1))
                .andExpect(jsonPath(CODE_PATH).value(200))
                .andExpect(jsonPath(ROWS_PATH).isArray())
                .andExpect(jsonPath("$.rows[0].gameRoleName").value("TestRoleName"));

        verify($!{serviceObjName}, times(1)).pageVo(any($!{queryName}.class));
    }

    /**
     * 测试查询所有数据接口 /list
     */
    @Test
    void testSelectAll() throws Exception {
        // 1. 模拟 Service 返回数据
        List<$!voName> mockList = Collections.singletonList(new $!voName());
        // Service 方法: listVo(req)
        when($!{serviceObjName}.listVo(any($!{queryName}.class))).thenReturn(mockList);

        // 2. 构造请求体
        $!queryName query = new $!queryName();
        String jsonQuery = objectMapper.writeValueAsString(query);

        // 3. 执行请求并验证
        mockMvc.perform(post(BASE_URL + "/list")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(jsonQuery))
                .andExpect(status().isOk())
                .andExpect(jsonPath(CODE_PATH).value(200))
                .andExpect(jsonPath(ROWS_PATH).isArray())
                .andExpect(jsonPath("$.rows.length()").value(1));

        verify($!{serviceObjName}, times(1)).listVo(any($!{queryName}.class));
    }

    /**
     * 测试通过主键查询单条数据接口 /{id}
     */
    @Test
    void testSelectOne() throws Exception {
        // 1. 模拟 Service 返回数据
        $!voName mockVo = new $!voName();
        // Service 方法: getCustById(id)
        when($!{serviceObjName}.getCustById(any(Serializable.class))).thenReturn(mockVo);

        // 2. 执行请求并验证 (AjaxResult 结构验证)
        mockMvc.perform(get(BASE_URL + "/{id}", 1L))
                .andExpect(status().isOk())
                .andExpect(jsonPath(CODE_PATH).value(200))
                .andExpect(jsonPath("$.data").exists());

        verify($!{serviceObjName}, times(1)).getCustById(any(Serializable.class));
    }

    /**
     * 测试新增数据接口 /save
     */
    @Test
    void testInsert() throws Exception {
        // 1. 模拟 Service 返回成功 (返回 true 或 false)
        // Service 方法: saveCust(dto)
        when($!{serviceObjName}.saveCust(any($!{dtoName}.class))).thenReturn(true);

        // 2. 构造请求体
        $!dtoName dto = new $!dtoName();
        String jsonDto = objectMapper.writeValueAsString(dto);

        // 3. 执行请求并验证 (AjaxResult 结构验证)
        mockMvc.perform(post(BASE_URL + "/save")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(jsonDto))
                .andExpect(status().isOk())
                .andExpect(jsonPath(CODE_PATH).value(200));

        verify($!{serviceObjName}, times(1)).saveCust(any($!{dtoName}.class));
    }

    /**
     * 测试修改数据接口 /update
     */
    @Test
    void testUpdate() throws Exception {
        // 1. 模拟 Service 返回成功 (返回 true 或 false)
        // Service 方法: updateCustById(dto)
        when($!{serviceObjName}.updateCustById(any($!{dtoName}.class))).thenReturn(true);

        // 2. 构造请求体
        $!dtoName dto = new $!dtoName();
        String jsonDto = objectMapper.writeValueAsString(dto);

        // 3. 执行请求并验证 (AjaxResult 结构验证)
        mockMvc.perform(put(BASE_URL + "/update")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(jsonDto))
                .andExpect(status().isOk())
                .andExpect(jsonPath(CODE_PATH).value(200));

        verify($!{serviceObjName}, times(1)).updateCustById(any($!{dtoName}.class));
    }

    /**
     * 测试删除数据接口 (Query Param) /
     */
    @Test
    void testDelete() throws Exception {
        // 1. 模拟 Service 返回成功 (返回 true 或 false)
        List<Long> idList = LongStream.rangeClosed(1, 3).boxed().collect(Collectors.toList());
        // Service 方法: removeByIds(idList)
        when($!{serviceObjName}.removeByIds(anyList())).thenReturn(true);

        // 2. 执行请求并验证 (AjaxResult 结构验证)
        mockMvc.perform(delete(BASE_URL)
                        // 参数名与 Controller 的 @RequestParam("idList") 匹配
                        .param("idList", "1", "2", "3") 
                        .contentType(MediaType.APPLICATION_JSON))
                .andExpect(status().isOk())
                .andExpect(jsonPath(CODE_PATH).value(200));

        // 验证 Mockito 调用的参数 (使用 eq(idList) 精确匹配参数值)
        verify($!{serviceObjName}, times(1)).removeByIds(eq(idList));
    }

    /**
     * 测试批量删除数据接口 (Request Body) /batch
     */
    @Test
    void testBatchDel() throws Exception {
        // 1. 模拟 Service 返回成功 (返回 true 或 false)
        List<Long> idList = LongStream.rangeClosed(10, 12).boxed().collect(Collectors.toList());
        // Service 方法: removeByIds(idList)
        when($!{serviceObjName}.removeByIds(anyList())).thenReturn(true);

        // 2. 构造请求体
        String jsonIds = objectMapper.writeValueAsString(idList);

        // 3. 执行请求并验证 (AjaxResult 结构验证)
        mockMvc.perform(delete(BASE_URL + "/batch")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(jsonIds))
                .andExpect(status().isOk())
                .andExpect(jsonPath(CODE_PATH).value(200));

        // 验证 Mockito 调用的参数 (使用 eq(idList) 精确匹配参数值)
        verify($!{serviceObjName}, times(1)).removeByIds(eq(idList));
    }
}

