<script setup name="$!{EntityName}">
import * as ${EntityName}Api from "@/api/$!{tablePrefix}/$!{pathEntityName}/$!{pathEntityName}"

const { proxy } = getCurrentInstance()

const dataList = ref([])
const open = ref(false)
const loading = ref(true)
const showSearch = ref(true)
const ids = ref([])
const single = ref(true)
const multiple = ref(true)
const total = ref(0)
const title = ref("")
const dateRange = ref([])

const data = reactive({
  form: {},
  queryParams: {
    delFlag: 0,
    pageNum: 1,
    pageSize: 10
  },
  rules: {
  },
})

const { queryParams, form, rules } = toRefs(data)

/** 查询列表 */
function getList() {
  loading.value = true
  ${EntityName}Api.list${EntityName}(proxy.addDateRange(queryParams.value, dateRange.value)).then(response $arrow {
    dataList.value = response.rows
    total.value = response.total
    loading.value = false
  })
}

/** 取消按钮 */
function cancel() {
  open.value = false
  reset()
}

/** 表单重置 */
function reset() {
  form.value = {
#foreach($column in $tableInfo.fullColumn)
    $!column.name: undefined#if($foreach.hasNext),#end

#end
  }
  proxy.resetForm("formRef")
}

/** 搜索按钮操作 */
function handleQuery() {
  queryParams.value.pageNum = 1
  getList()
}

/** 重置按钮操作 */
function resetQuery() {
  dateRange.value = []
  proxy.resetForm("queryRef")
  handleQuery()
}

/** 新增按钮操作 */
function handleAdd() {
  reset()
  open.value = true
  title.value = "添加$!{tableInfo.comment}"
}

/** 多选框选中数据 */
function handleSelectionChange(selection) {
  ids.value = selection.map(item $arrow item.$!pkName)
  single.value = selection.length != 1
  multiple.value = !selection.length
}

/** 修改按钮操作 */
function handleUpdate(row) {
  reset()
  const $!pkName = row.$!pkName || ids.value
  ${EntityName}Api.${entityName}($!pkName).then(response $arrow {
    form.value = JSON.parse(JSON.stringify(response.data))
    open.value = true
    title.value = "修改$!{tableInfo.comment}"
  })
}

/** 提交按钮 */
function submitForm() {
  proxy.${dollar}refs["formRef"].validate(valid $arrow {
    if (valid) {
      if (form.value.$!pkName != undefined) {
        ${EntityName}Api.update${EntityName}(form.value).then(response $arrow {
          proxy.${dollar}modal.msgSuccess("修改成功")
